from ail import file_size
class ManifestFile:

    def __init__(self, path: str, size: int):
        self.path = path
        self.size = size

def manifest_empty() -> list[ManifestFile]:
    rows = []
    return rows

def manifest_add(rows: list[ManifestFile], path: str) -> int:
    size = file_size(path)
    rows.append(ManifestFile(path, size))
    return len(rows)

def manifest_total(rows: list[ManifestFile]) -> int:
    total = 0
    for row in rows:
        total += row.size
    return total

def manifest_by_path(rows: list[ManifestFile]) -> list[ManifestFile]:
    ordered = sorted(rows, key=lambda row: row.path)
    return ordered
